# Helper to strip .py and format tag name
def tag_name(file):
  return f"review-{file[:-3]}"

files = ['billing.py', 'lexer.py', 'codec.py', 'metrics.py', 'worker.py', 'search.py', 'auth.py', 'client.py', 'import.py', 'queue.py', 'server.py', 'config.py', 'eval.py', 'router.py']
results = []
for f in files:
  results.append(git_last_commit(f))
tags = []
for i, r in enumerate(results):
  if r['author'] == 'Hugo Mensah':
    tags.append({'tag': tag_name(files[i]), 'commit': r['commit']})
print(tags)

